<?php namespace App\Http\Controllers\Purchasing; use App\Http\Controllers\Controller; use App\Models\{Product,Purchase,Supplier,Warehouse}; use App\Services\PurchasingService; use Illuminate\Http\Request; class PurchaseController extends Controller { public function index(){return view('purchasing.purchases.index',['purchases'=>Purchase::with(['supplier','warehouse'])->latest()->paginate(15)]);} public function create(){return view('purchasing.purchases.create',['suppliers'=>Supplier::where('is_active',true)->orderBy('name')->get(),'warehouses'=>Warehouse::orderBy('name')->get(),'products'=>Product::where('is_active',true)->orderBy('name')->get(['id','name','sku','cost_price'])]);} public function store(Request $r,PurchasingService $service){$d=$r->validate(['supplier_id'=>['required','integer','exists:suppliers,id'],'warehouse_id'=>['required','integer','exists:warehouses,id'],'discount'=>['nullable','numeric','min:0'],'tax'=>['nullable','numeric','min:0'],'expected_at'=>['nullable','date'],'note'=>['nullable','string','max:1000'],'items'=>['required','array','min:1','max:100'],'items.*.product_id'=>['required','integer','distinct','exists:products,id'],'items.*.quantity'=>['required','numeric','gt:0','max:100000'],'items.*.unit_cost'=>['required','numeric','min:0','max:999999999']]);$p=$service->createPurchase(Supplier::findOrFail($d['supplier_id']),Warehouse::findOrFail($d['warehouse_id']),$d['items'],$d['discount']??0,$d['tax']??0,$d['expected_at']??null,$d['note']??null,$r);return redirect()->route('purchases.show',$p)->with('success','Purchase order created: '.$p->purchase_no);} public function show(Purchase $purchase){$purchase->load(['supplier','warehouse','items.product','returns']);return view('purchasing.purchases.show',compact('purchase'));} public function order(Purchase $purchase,Request $r,PurchasingService $s){$s->markOrdered($purchase,$r);return back()->with('success','Purchase order marked as ordered.');} public function receive(Purchase $purchase,Request $r,PurchasingService $s){$d=$r->validate(['items'=>['required','array','min:1'],'items.*.purchase_item_id'=>['required','integer'],'items.*.quantity'=>['nullable','numeric','min:0','max:100000']]);$s->receive($purchase,$d['items'],$r);return back()->with('success','Stock receiving completed.');} public function returnStock(Purchase $purchase,Request $r,PurchasingService $s){$d=$r->validate(['reason'=>['nullable','string','max:1000'],'items'=>['required','array','min:1'],'items.*.purchase_item_id'=>['required','integer'],'items.*.quantity'=>['nullable','numeric','min:0','max:100000']]);$ret=$s->returnStock($purchase,$d['items'],$d['reason']??null,$r);return back()->with('success','Purchase return '.$ret->return_no.' completed.');} }
